                value: "[{\"Name\":\"Agender\",\"Description\":\"Not having a gender or identifying with a gender. They may describe themselves as being gender neutral or genderless\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Abrosexual\",\"Description\":\"Abrosexuality is described as an individual who experiences their sexuality change frequently. It can fluctuate between different sexualities often\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Androgynosexual\",\"Description\":\"An androgynosexual describes a person who is sexually attracted to men and women, particularly those of androgynous appearance\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Androsexual\",\"Description\":\"An androsexual is anyone who has sexual feelings towards masculinity. This term is usually used by Sexuality-queer individuals who do not fall within heterosexuality or homosexuality\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Aromantic \",\"Description\":\"A person who is aromantic does not experience romantic attraction. This person does not have to identify as asexual \\u0026 they still may experience sensual \\u0026 aesthetic attraction\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Asexual \",\"Description\":\"Asexual is the term used to describe a person who feels little to no sexual attraction to anyone\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Biromantic \",\"Description\":\"A person who is romantically attracted to two sexes or Sexualitys. Biromantic asexuals seek romantic relationships for companionship, affection, and intimacy, but they are not sexually attracted to their romantic partners\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Bisexuality \",\"Description\":\"Bisexuals are sexually attracted to two or more Sexualitys\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Ceterosexual \",\"Description\":\"Someone who experiences sexual/romantic attraction only to non-binary people. This label is used as a non-problematic term for skoliosexuality only to be used by non-binary people\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Demisexual \",\"Description\":\"Demisexual refers to a person who doesn\\u2019t experience sexual attraction unless they form an emotional connection\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Demiromantic \",\"Description\":\"This term is a type of grey-romantic who only experiences romantic attraction after developing an emotional connection. They do not experience primary romantic attraction, but are capable of secondary romantic attraction\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Finsexual \",\"Description\":\"The attraction to women, females and femininity \",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Gay\",\"Description\":\"A person who identifies as homosexual\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Gynosexual \",\"Description\":\"Anyone who has sexual feelings towards a woman or femininity. The term can be useful when describing the sexual orientation of an individual with a non-binary Sexuality identity\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Grey-Romantic\",\"Description\":\"A grey-romantic is a person with a romantic orientation that is somewhere between aromantic \\u0026 romantic\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Heterosexual \",\"Description\":\"A person sexually attracted to people of the opposite sex\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Homosexuality \",\"Description\":\"A person sexually attracted to people of ones own sex\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Heteroromantic \",\"Description\":\"Romantically attracted to a member of the opposite sex or Sexuality. They may seek romantic intimacy but they\\u2019re not sexually attracted to partners\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Homoromantic \",\"Description\":\"Romantically attracted to someone of the same sex or Sexuality. They may seek romantic intimacy but they\\u2019re not sexually attracted to partners\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Lesbian\",\"Description\":\"A homosexual woman whose emotional, romantic and sexual feelings are towards women\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Omnisexual\",\"Description\":\"Omnisexuals are attracted to all genders,=. Gender can still be a factor in their attraction, unlike pansexuals, who don\\u2019t care about gender\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Pansexuality\",\"Description\":\"A person whose romantic and/or sexual attraction towards others is not limited by sex or gender\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Panromantic\",\"Description\":\"Is a person that can be romantically attracted to all genders, but not sexually\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Pomosexuality\",\"Description\":\"Refers to non-orientation in which people disregard sexuality labels altogether. Basically, labels are seen as superficial and insignificant to someone who identities as pomosexual\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Polysexual\",\"Description\":\"Is the attract to some, but not all, genders. They may be attracted to any combination of  possible genders, including binary \\u0026 non-binary\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Queer\",\"Description\":\"An LGBTQ\\u002B term the community is reclaiming. An identity label that is non-specific about a persons sexual orientation\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Questioning\",\"Description\":\"To be unsure of or re-examining ones previous assumption of sexual orientation\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Straight\",\"Description\":\"An heterosexual\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Skoliosexual\",\"Description\":\"The attraction to non-binary individuals\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"},{\"Name\":\"Sapiosexual\",\"Description\":\"Sexually attracted to intelligence or the human mind\",\"Active\":true,\"ReadOnly\":false,\"CreatedOn\":\"2026-01-01T00:00:00\",\"CreatedBy\":\"MssBase.Service\",\"UpdatedOn\":\"2026-01-01T00:00:00\",\"UpdatedBy\":\"MssBase.Service\"}]");
        }
    }
